import io
import os
import re
from collections import OrderedDict

import numpy as np

from dpdata.periodic_table import Element


def _parse_float_array(value: str) -> np.ndarray:
    """Parse a whitespace-separated string into a float array."""
    return np.array([float(part) for part in value.split()])


def _voigt_to_matrix(voigt: np.ndarray) -> np.ndarray:
    """Build a symmetric 3x3 tensor from Voigt order ``xx yy zz yz xz xy``."""
    matrix = np.zeros((3, 3), dtype=np.float64)
    matrix[0, 0] = voigt[0]
    matrix[1, 1] = voigt[1]
    matrix[2, 2] = voigt[2]
    matrix[1, 2] = matrix[2, 1] = voigt[3]
    matrix[0, 2] = matrix[2, 0] = voigt[4]
    matrix[0, 1] = matrix[1, 0] = voigt[5]
    return matrix


def _parse_tensor(value: str, field_name: str) -> np.ndarray:
    """Parse a 3x3 tensor from a 9- or 6-component header field.

    A 9-component value is interpreted in row-major order; a 6-component
    value is interpreted in Voigt order ``xx yy zz yz xz xy``.
    """
    array = _parse_float_array(value)
    if array.size == 9:
        return array.reshape(3, 3)
    if array.size == 6:
        return _voigt_to_matrix(array)
    raise RuntimeError(
        f"expected 6 or 9 components in extxyz {field_name} field, got {array.size}"
    )


def _stress_to_virial(stress: np.ndarray, cell: np.ndarray) -> np.ndarray:
    """Convert an ASE-style stress tensor to the cell virial tensor.

    Following the ASE convention, ``virial = - volume * stress``.
    """
    volume = abs(np.linalg.det(cell))
    return -volume * stress


